	return out
}

func TestAHiddenColumnTakesNoSpace(t *testing.T) {
	for _, width := range []int{50, 80, 120, 175} {
		t.Run(fmt.Sprintf("width %d", width), func(t *testing.T) {
			m := hiddenModel(width, -1)
			m.SetColumnHidden(hiddenColumn, true)
