// TestEveryColumnDeclaresItsSizing rather than by this function: a zero value
// that quietly means something is D12, and the point is that no column arrives
// here undeclared at all.
//
// A MaxWidth under the floor is a contradictory declaration; the floor wins,
// because a column narrower than its own header says less than nothing.
func wantFor[T any](c Column[T], measured int) int {
	floor := floorFor(c)
	if c.Sizing != SizingContent {
		return floor
	}
	want := max(measured, floor)
	if c.MaxWidth > 0 {
		want = min(want, max(c.MaxWidth, floor))
	}
	return want
}

// solveWidths lays the columns out in a viewport of this width, returning one
// width per declared column — zero for a column that had to be dropped.
//
// measured carries the widest content each column has produced, as the model
// last measured it; it may be shorter than columns, and a missing entry reads
// as no measurement, which leaves a SizingContent column at its MinWidth.
//
// The result always sums to exactly the room the kept columns have, so the
// rendered line spans the viewport interior at every width (Rule 116).
func solveWidths[T any](columns []Column[T], viewportWidth int, measured []int) []int {
	if len(columns) == 0 {
		return nil
	}

	kept := make([]int, len(columns))
	for i := range kept {
		kept[i] = i
	}

	for {
		available := availableFor(viewportWidth, len(kept))
		if available <= 0 {
			// Not even room for this many paddings. Dropping a column hands two
			// cells back, so the loop makes progress; with one column left
			// there is genuinely nothing to draw.
			if len(kept) == 1 {
				return make([]int, len(columns))
			}
			kept = drop(columns, kept)
			continue
		}

		widths := make([]int, len(columns))
		shortfall := fitInto(columns, kept, widths, available, measured)
		if shortfall == 0 {
			return widths
		}
		if len(kept) == 1 {
			// The end of the line: one column, still too wide. It gives up the
			// remainder itself, below its own declared minimum, because the
			// alternative is not rendering the table at all.
			takeFrom(widths, kept, shortfall)
			return widths
		}
		kept = drop(columns, kept)
	}
}

// fitInto solves the kept columns into available and returns what it could not
// reclaim without removing a column.
func fitInto[T any](columns []Column[T], kept, widths []int, available int, measured []int) int {
	total := 0
	for _, i := range kept {
		widths[i] = wantFor(columns[i], measureOf(measured, i))
		total += widths[i]
	}

	switch {
	case total < available:
		grow(columns, kept, widths, available-total)
	case total > available:
		if nextYields(columns, kept) {
			// Cut only the Optional content columns; what remains is handed
			// to drop(), which removes the yielding column.
			return shrinkContentWhere(columns, kept, widths, total-available,
				func(c Column[T]) bool { return c.Optional })
		}
		return shrinkContent(columns, kept, widths, total-available)
	}
	return 0
}

// measureOf reads a measurement that may not have been taken. An unmeasured
// column is not a zero-width one: it falls back to what it declared.
func measureOf(measured []int, i int) int {
	if i < len(measured) {
		return measured[i]
	}
	return 0
}

// drop removes one column from the kept set: the rightmost DropFirst one, else
// the rightmost Optional one, and only when there is neither, the rightmost of
// all.
//
// Right to left because the column order is already an order of importance in
// every table here — the identifying column is first — so degrading from the
// right sheds the least. DropFirst is the exception a gauge needs: its place on
// screen says which number it illustrates, not how much it is worth (§3.71).
// The first column is never dropped: a table with no columns at all is not a
// narrower table, it is a blank one.
func drop[T any](columns []Column[T], kept []int) []int {
	at := dropAt(columns, kept)
	return append(kept[:at:at], kept[at+1:]...)
}

// dropAt returns the position in kept of the column drop() removes. drop and
// nextYields both call it, so they cannot disagree on which column goes next.
func dropAt[T any](columns []Column[T], kept []int) int {
	for _, wanted := range []func(Column[T]) bool{
		func(c Column[T]) bool { return c.Optional && c.DropFirst },
		func(c Column[T]) bool { return c.Optional },
	} {
		if i, ok := rightmost(columns, kept, wanted); ok {
			return i
		}
	}
	return len(kept) - 1
}

// nextYields reports whether the column drop() would remove next is an
// Optional column carrying YieldsToContent. False when only the first column
// is left, which is never dropped.
func nextYields[T any](columns []Column[T], kept []int) bool {
	if len(kept) < 2 {
		return false
	}
	c := columns[kept[dropAt(columns, kept)]]
	return c.Optional && c.YieldsToContent
}

// rightmost finds the last kept column matching want, never the first one.
func rightmost[T any](columns []Column[T], kept []int, want func(Column[T]) bool) (int, bool) {
// SetHeight sets the number of rows shown. The window is re-clamped: a table
// that just got shorter can leave the cursor below its own last visible row.
func (m *Model[T]) SetHeight(h int) {
	m.table.SetHeight(max(h, 1))
	m.clampOffset()
}

// Focus and Blur move the keyboard between two tables sharing a viewport, which
// is what the status view does with its monitors and its certificates.
func (m *Model[T]) Focus() {
	m.table.Focus()
	m.afterCursorMove()
}

func (m *Model[T]) Blur() {
	m.table.Blur()
	m.setStyles(theme.BlurredTableStyles())
}

// Resize recomputes the column widths for a viewport of this width (Rule 116).
// The width passed is the full viewport width, borders included; the borders and
// the per-cell padding are subtracted here so no caller has to remember to.
func (m *Model[T]) Resize(width, height int) {
	m.width = width
	m.promote()
	widths := solveWidths(m.cfg.Columns, width, m.measured)

	cols := m.table.Columns()
	for i := range cols {
		cols[i].Width = widths[i]
		cols[i].Title = m.titleFor(i)
	}
	m.table.SetColumns(cols)
	m.bar.Resize(width)
	if height > 0 {
		m.SetHeight(height)
	}
	m.afterCursorMove() // the selected row is pinned to this width
}

// The sort arrows, and what they cost. Named because widths.go has to reserve
// room for them: a column's MinWidth is the view's statement about its content,
// and it knows nothing about two cells this package appends to the header.
const (
	sortArrowAsc  = " ▲"
	sortArrowDesc = " ▼"
)

// titleFor returns a column's header, with a sort arrow on the active one.
func (m *Model[T]) titleFor(i int) string {
	if i != m.sortColumn {
		return m.cfg.Columns[i].Title
	}
	if m.sortDesc {
		return m.cfg.Columns[i].Title + sortArrowDesc
	}
	return m.cfg.Columns[i].Title + sortArrowAsc
}

// CycleSort advances the sort: the column's first direction (ascending, or
// descending when it is DescFirst), then the other, then on to the next
// sortable column (Rule 111's `.`). Returns to no sort after the last one when
// the table opened unsorted, so the original order stays reachable.
func (m *Model[T]) CycleSort() {
	sortable := m.sortableColumns()
	if len(sortable) == 0 {
		return
	}
	switch {
	case m.sortColumn < 0:
		m.sortColumn = sortable[0]
		m.sortDesc = m.cfg.Columns[m.sortColumn].DescFirst
	case m.sortDesc == m.cfg.Columns[m.sortColumn].DescFirst: // first direction shown
		m.sortDesc = !m.sortDesc
	default:
		next := m.nextSortable(sortable)
		m.sortColumn, m.sortDesc = next, next >= 0 && m.cfg.Columns[next].DescFirst
	}
	m.rebuild()
	m.Resize(m.width, 0) // the arrow moved
}

// nextSortable returns the column after the current one, wrapping to the first —
