package security

import (
	"github.com/anthnel/devdesk/internal/remediation"
	"github.com/anthnel/devdesk/internal/scan"
)

// fixStatus is the fix line of a finding detail, in words: a colour or a key
// name alone would not say it (Rule 134), so the status never names a key.
type fixStatus struct {
	Label   string // words, never a colour alone; "" = no status line
	Detail  string // reason, MissingFor text, catalog rule title, or ""
	Warning string // remediation.Rule.Warning, or ""
}

// Status labels. The tests spell them out too, on purpose: they are UI text.
const (
	labelFixAvailable   = "Fix available"
	labelNoFixAvailable = "No fix available"
	labelBuiltInFix     = "Built-in fix available"
	labelInstanceDecl   = "No built-in fix for this instance"
	labelImageTarget    = "No built-in fix here"
	labelNoBuiltInFix   = "No built-in fix"
)

